// sglang's DSA indexer top-k on gfx950: each row's 2048 highest of its first lengths scores, as the
// slots of its sequence's page_size=1 page table (the cu_seqlens_q range holding the row); a row of
// at most 2048 scores takes all of them in order, then -1. A radix select on each score's
// order-preserving 32-bit key. Tables up to ROW_MAX wide take a block a row (row_kernel); wider ones
// launches that never wait on one another: a histogram of the top 12 bits; one of the next 12 inside
// the bin holding the 2048th; the keys above that 24-bit threshold written, and those on it counted by
// their last 8 bits and kept as candidates; then the rest of the 2048 picked among them, by a block from
// the kept candidates, or, past CAP, by every block of the row from its slice.
#include <ATen/ATen.h>
#include <ATen/hip/HIPContext.h>
#include <ATen/hip/impl/HIPGuardImplMasqueradingAsCUDA.h>
#include <c10/hip/HIPException.h>
#include <hip/hip_runtime.h>
#include <torch/library.h>

namespace dsa_topk {
namespace {

constexpr int TOPK    = 2048;
constexpr int THREADS = 256;
constexpr int WAVES   = THREADS / 64;
constexpr int BINS    = 4096;  // a 12-bit digit
constexpr int PER     = BINS / THREADS;  // the bins a thread sums
constexpr int CAP     = 16384;  // candidates a row keeps; past them refine rescans the row's slices
constexpr int TIES    = 1024;   // candidates a scatter block stages
constexpr int BLOCKS  = 1024;   // blocks a pass spreads over its rows
constexpr int ITEMS   = 32;     // scores a pass thread loads at once

// zeroed each call
struct RowState {
    unsigned hist0[BINS];  // the keys' top 12 bits, exact from the threshold's bin up
    unsigned hist1[BINS];  // the next 12, of the keys in the threshold's top bin
    unsigned hist2[256];   // the last 8, of the keys on the 24-bit threshold
    unsigned winners;      // keys above the 24-bit threshold, written
    unsigned candidates;   // keys on it
    unsigned taken, ties;  // keys on it refine has written: above the 32-bit threshold, and on it
    unsigned pad[60];
};

struct Params {
    const float *score;
    const int   *lengths;
    const int   *table;  // [n_seqs, n_slots]
    const int   *cu_seqlens;
    int         *out;    // [rows, TOPK]
    RowState    *state;  // [rows]
    uint2       *cands;  // [rows, CAP]: key, position
    int          n_candidates;
    int          n_seqs;
    int          n_slots;
    unsigned     per_block;   // a pass block's positions
    unsigned     per_block0;  // hist0's
};

// a block of W waves' scan scratch
template <int W> struct Sums {
    unsigned wave[W];
    unsigned result[2];
};
using Shared = Sums<WAVES>;

// larger floats, larger keys
__device__ __forceinline__ uint32_t key_of(float x) {
    const uint32_t b = __float_as_uint(x);
    return (b & 0x80000000u) ? ~b : (b | 0x80000000u);
}

// the lane's slot among the wave's lanes where on holds, past counter, which grows by their count: one
// atomic a wave; whole waves call it
__device__ __forceinline__ unsigned wave_slot(unsigned *counter, bool on) {
    const uint64_t m = __ballot(on);
    if (!m) return 0;
    const int lane = threadIdx.x & 63, first = __builtin_ctzll(m);
    unsigned  base = 0;
    if (lane == first) base = atomicAdd(counter, static_cast<unsigned>(__popcll(m)));
    return __shfl(base, first) + static_cast<unsigned>(__popcll(m & ((1ull << lane) - 1)));
}

// the sum of own over the block's threads above this one
template <int W> __device__ __forceinline__ unsigned above_of(unsigned own, Sums<W> &s) {
    const int lane = threadIdx.x & 63, wave = threadIdx.x >> 6;
    unsigned  v    = own;
#pragma unroll
    for (int d = 1; d < 64; d <<= 1) {
        const unsigned u = __shfl_down(v, d);
        if (lane + d < 64) v += u;
    }
    if (lane == 0) s.wave[wave] = v;
    __syncthreads();
    unsigned above = v - own;
    for (int w = wave + 1; w < W; ++w) above += s.wave[w];
    __syncthreads();
    return above;
}

// thread t's bins of a histogram, [4 N t, 4 N t + 4 N)
template <int N> __device__ __forceinline__ void load_bins(const unsigned *hist, uint4 (&bins)[N]) {
#pragma unroll
    for (int i = 0; i < N; ++i) bins[i] = reinterpret_cast<const uint4 *>(hist + threadIdx.x * 4 * N)[i];
}

// The bin holding the need-th largest key of a histogram whose thread t holds bins [4 N t, 4 N t + 4 N),
// and the count of keys above it (bin 0 and 0 when it holds fewer); every thread of the block returns
// them.
template <int N, int W> __device__ uint2 threshold(const uint4 (&bins)[N], unsigned need, Sums<W> &s) {
    constexpr int   P   = 4 * N;
    if (threadIdx.x == 0) s.result[0] = s.result[1] = 0;
    const unsigned *b   = reinterpret_cast<const unsigned *>(bins);
    unsigned        own = 0;
#pragma unroll
    for (int i = 0; i < P; ++i) own += b[i];
    unsigned above = above_of(own, s);
    if (above < need && above + own >= need) {
#pragma unroll
        for (int i = P - 1; i >= 0; --i) {
            if (above < need && above + b[i] >= need) {
                s.result[0] = threadIdx.x * P + i;
                s.result[1] = above;
            }
            above += b[i];
        }
    }
    __syncthreads();
    const uint2 r = {s.result[0], s.result[1]};
    __syncthreads();
    return r;
}

// the 24-bit threshold of the row's top TOPK and the keys above it
__device__ __forceinline__ uint2 threshold24(const RowState &st, Shared &s) {
    uint4 bins0[PER / 4], bins1[PER / 4];
    load_bins(st.hist0, bins0);
    load_bins(st.hist1, bins1);
    const uint2 t0 = threshold(bins0, TOPK, s);
    const uint2 t1 = threshold(bins1, TOPK - t0.y, s);
    return {(t0.x << 12) | t1.x, t0.y + t1.y};
}

__device__ __forceinline__ int sequence_of(const Params &p, int row) {
    int lo = 0, hi = p.n_seqs - 1;
    while (lo < hi) {
        const int mid = (lo + hi + 1) >> 1;
        if (p.cu_seqlens[mid] <= row) lo = mid;
        else hi = mid - 1;
    }
    return lo;
}

// A pass block's slice of its row's live positions, empty when the row takes all of them, walked
// ITEMS scores a thread at a time; its first scores load when it is made.
// unsigned positions: a row of up to 2^31 - 1 scores, plus a pass's stride, stays below 2^32
struct Slice {
    const float *score;
    unsigned     begin, end;
    float        v[ITEMS];

    __device__ Slice(const Params &p, int row, unsigned per_block) {
        const unsigned len = p.lengths[row];
        score              = p.score + static_cast<size_t>(row) * p.n_candidates;
        begin              = len <= TOPK ? 0 : blockIdx.y * per_block;
        end                = len <= TOPK ? 0 : min(begin + per_block, len);
        load(begin);
    }
    __device__ __forceinline__ void load(unsigned base) {
#pragma unroll
        for (int j = 0; j < ITEMS; ++j) {
            const unsigned i = base + j * THREADS + threadIdx.x;
            v[j]             = i < end ? score[i] : 0.f;
        }
    }
    // f(i, key) for each position; whole waves call it (i >= end past the slice) so that its ballots
    // see all 64 lanes
    template <typename F> __device__ __forceinline__ void walk(F f) {
        for (unsigned base = begin; base < end; base += THREADS * ITEMS) {
            if (base != begin) load(base);
#pragma unroll
            for (int j = 0; j < ITEMS; ++j) f(base + j * THREADS + threadIdx.x, key_of(v[j]));
        }
    }
};

__global__ __launch_bounds__(THREADS) void hist0_kernel(Params p) {
    __shared__ __attribute__((aligned(16))) unsigned s_hist[BINS];
    __shared__ Shared   s;
    Slice sl(p, blockIdx.x, p.per_block0);
    if (sl.begin >= sl.end) return;
    for (int i = threadIdx.x; i < BINS; i += THREADS) s_hist[i] = 0;
    __syncthreads();
    sl.walk([&](unsigned i, uint32_t k) {
        if (i < sl.end) atomicAdd(&s_hist[k >> 20], 1u);
    });
    __syncthreads();
    // only the block's bins from its own threshold up: the row's threshold bin and those above it
    // are among them, and the bins below never matter
    uint4 bins[PER / 4];
    load_bins(s_hist, bins);
    const unsigned low  = threshold(bins, TOPK, s).x;
    unsigned      *hist = p.state[blockIdx.x].hist0;
    for (int i = threadIdx.x; i < BINS; i += THREADS)
        if (i >= low && s_hist[i]) atomicAdd(&hist[i], s_hist[i]);
}

__global__ __launch_bounds__(THREADS) void hist1_kernel(Params p) {
    __shared__ __attribute__((aligned(16))) unsigned s_hist[BINS];
    __shared__ Shared   s;
    Slice sl(p, blockIdx.x, p.per_block);
    if (sl.begin >= sl.end) return;
    RowState &st = p.state[blockIdx.x];
    uint4     bins[PER / 4];
    load_bins(st.hist0, bins);
    for (int i = threadIdx.x; i < BINS; i += THREADS) s_hist[i] = 0;
    const uint2 t0 = threshold(bins, TOPK, s);
    sl.walk([&](unsigned i, uint32_t k) {
        if (i < sl.end && (k >> 20) == t0.x) atomicAdd(&s_hist[(k >> 8) & (BINS - 1)], 1u);
    });
    __syncthreads();
    for (int i = threadIdx.x; i < BINS; i += THREADS)
        if (s_hist[i]) atomicAdd(&st.hist1[i], s_hist[i]);
}

__global__ __launch_bounds__(THREADS) void scatter_kernel(Params p) {
    __shared__ Shared s;
    // the block's winners and candidates, staged so that it reserves their space with one atomic
    __shared__ unsigned s_win[TOPK];
    __shared__ uint2    s_tie[TIES];
    __shared__ unsigned s_low[256];  // the candidates' last 8 bits
    __shared__ unsigned s_n_win, s_n_tie, s_win_base, s_tie_base;
    const int row = blockIdx.x;
    Slice     sl(p, row, p.per_block);
    if (sl.begin >= sl.end) return;
    RowState &st = p.state[row];
    if (threadIdx.x == 0) s_n_win = s_n_tie = 0;
    for (int i = threadIdx.x; i < 256; i += THREADS) s_low[i] = 0;
    const uint2 t     = threshold24(st, s);
    uint2      *cands = p.cands + static_cast<size_t>(row) * CAP;
    sl.walk([&](unsigned i, uint32_t k) {
        if (i >= sl.end) return;
        if ((k >> 8) > t.x) {
            s_win[atomicAdd(&s_n_win, 1u)] = i;  // fewer than TOPK in the row
        } else if ((k >> 8) == t.x) {
            atomicAdd(&s_low[k & 0xFF], 1u);
            const unsigned slot = atomicAdd(&s_n_tie, 1u);
            if (slot < TIES) s_tie[slot] = {k, i};
        }
    });
    __syncthreads();
    for (int i = threadIdx.x; i < 256; i += THREADS)
        if (s_low[i]) atomicAdd(&st.hist2[i], s_low[i]);
    // a block past TIES keeps none, and pushes the row past CAP: refine then rescans it
    const unsigned n_tie = s_n_tie <= TIES ? s_n_tie : 0;
    if (threadIdx.x == 0) {
        s_win_base = s_n_win ? atomicAdd(&st.winners, s_n_win) : 0;
        s_tie_base = s_n_tie ? atomicAdd(&st.candidates, n_tie ? n_tie : CAP + 1) : 0;
    }
    __syncthreads();
    const int *table = p.table + static_cast<size_t>(sequence_of(p, row)) * p.n_slots;
    int       *out   = p.out + static_cast<size_t>(row) * TOPK;
    for (unsigned j = threadIdx.x; j < s_n_win; j += THREADS) out[s_win_base + j] = table[s_win[j]];
    for (unsigned j = threadIdx.x; j < n_tie; j += THREADS)
        if (s_tie_base + j < CAP) cands[s_tie_base + j] = s_tie[j];
}

__global__ __launch_bounds__(THREADS) void refine_kernel(Params p) {
    __shared__ Shared   s;
    __shared__ unsigned s_taken, s_ties;
    const int      row  = blockIdx.x;
    RowState      &st   = p.state[row];
    const unsigned n    = st.candidates;  // 0 for a short row
    const bool     kept = n <= CAP;
    // a short row and the kept candidates are one block's; past CAP every block rescans its slice
    if (kept && blockIdx.y) return;
    const int  len   = p.lengths[row];
    int       *out   = p.out + static_cast<size_t>(row) * TOPK;
    const int *table = p.table + static_cast<size_t>(sequence_of(p, row)) * p.n_slots;
    if (len <= TOPK) {
        for (int i = threadIdx.x; i < TOPK; i += THREADS) out[i] = i < len ? table[i] : -1;
        return;
    }
    if (threadIdx.x == 0) s_taken = s_ties = 0;
    const uint2    t    = threshold24(st, s);
    const unsigned need = TOPK - t.y;  // >= 1, taken among the keys on the threshold
    uint4 bins[PER / 4] = {};  // bins 0 .. 255: the last 8 bits
    if (threadIdx.x < 256 / PER) load_bins(st.hist2, bins);
    const uint2 t2 = threshold(bins, need, s);
    // keys above t2 all go; of those on it, equal keys, any need - t2.y
    auto take = [&](unsigned *taken, unsigned *ties, bool on, uint32_t k, unsigned pos) {
        const bool     above = on && (k & 0xFF) > t2.x, tie = on && (k & 0xFF) == t2.x;
        const unsigned a = wave_slot(taken, above), b = wave_slot(ties, tie);
        if (above) out[t.y + a] = table[pos];
        if (tie && b < need - t2.y) out[t.y + t2.y + b] = table[pos];
    };
    if (kept) {
        const uint2 *cands = p.cands + static_cast<size_t>(row) * CAP;
        for (unsigned j0 = 0; j0 < n; j0 += THREADS) {
            const unsigned j = j0 + threadIdx.x;
            const uint2    c = j < n ? cands[j] : uint2{0, 0};
            take(&s_taken, &s_ties, j < n, c.x, c.y);
        }
    } else {
        Slice sl(p, row, p.per_block);
        sl.walk([&](unsigned i, uint32_t k) { take(&st.taken, &st.ties, i < sl.end && (k >> 8) == t.x, k, i); });
    }
}

// Narrow tables: a block a row. A pass over the row histograms the top 12 bits; a second writes the keys
// above the bin holding the 2048th and keeps those in it as candidates in LDS, their next 12 bits
// histogrammed; the rest of the 2048 are picked among the candidates by the last 20 bits. One launch,
// nothing to zero: what the wide tables' passes cost a short row is more than its whole time here.
constexpr int ROW_THREADS = 1024;
constexpr int ROW_ITEMS   = 8;      // scores a thread loads at once
constexpr int ROW_MAX     = 16384;  // the widest table a block a row takes, all of it candidates in LDS

struct RowShared {
    unsigned               hist[BINS];
    uint2                  cand[ROW_MAX];  // key, position
    Sums<ROW_THREADS / 64> sums;
    unsigned               n_cand, taken, ties;
};

// the bin of s.hist holding the need-th largest key and the keys above it, s.hist zeroed for the next digit
__device__ __forceinline__ uint2 hist_threshold(unsigned need, RowShared &s) {
    uint4 bins[BINS / ROW_THREADS / 4];
    load_bins(s.hist, bins);
    reinterpret_cast<uint4 *>(s.hist)[threadIdx.x] = uint4{0, 0, 0, 0};
    return threshold(bins, need, s.sums);
}

// f(i, key) for each of the row's first len positions, ROW_ITEMS loads in flight a thread
template <typename F> __device__ __forceinline__ void walk_row(const float *score, unsigned len, F f) {
    for (unsigned base = 0; base < len; base += ROW_THREADS * ROW_ITEMS) {
        float v[ROW_ITEMS];
#pragma unroll
        for (int j = 0; j < ROW_ITEMS; ++j) {
            const unsigned i = base + j * ROW_THREADS + threadIdx.x;
            v[j]             = i < len ? score[i] : 0.f;
        }
#pragma unroll
        for (int j = 0; j < ROW_ITEMS; ++j) {
            const unsigned i = base + j * ROW_THREADS + threadIdx.x;
            if (i < len) f(i, key_of(v[j]));
        }
    }
}

__global__ __launch_bounds__(ROW_THREADS) void row_kernel(Params p) {
    __shared__ __attribute__((aligned(16))) RowShared s;
    const int      row   = blockIdx.x;
    const unsigned len   = p.lengths[row];
    int           *out   = p.out + static_cast<size_t>(row) * TOPK;
    const int     *table = p.table + static_cast<size_t>(sequence_of(p, row)) * p.n_slots;
    if (len <= TOPK) {
        for (int i = threadIdx.x; i < TOPK; i += ROW_THREADS) out[i] = i < static_cast<int>(len) ? table[i] : -1;
        return;
    }
    const float *score = p.score + static_cast<size_t>(row) * p.n_candidates;
    for (int i = threadIdx.x; i < BINS; i += ROW_THREADS) s.hist[i] = 0;
    if (threadIdx.x == 0) s.n_cand = s.taken = s.ties = 0;
    __syncthreads();

    // the top 12 bits
    walk_row(score, len, [&](unsigned, uint32_t k) { atomicAdd(&s.hist[k >> 20], 1u); });
    __syncthreads();
    const uint2 t0 = hist_threshold(TOPK, s);
    // the keys above t0's bin written; those in it kept, their next 12 bits counted
    walk_row(score, len, [&](unsigned i, uint32_t k) {
        if ((k >> 20) > t0.x) {
            out[atomicAdd(&s.taken, 1u)] = table[i];
        } else if ((k >> 20) == t0.x) {
            atomicAdd(&s.hist[(k >> 8) & (BINS - 1)], 1u);
            s.cand[atomicAdd(&s.n_cand, 1u)] = {k, i};
        }
    });
    __syncthreads();
    const unsigned n_cand = s.n_cand;
    unsigned       need   = TOPK - t0.y;
    const uint2    t1     = hist_threshold(need, s);
    need -= t1.y;
    auto candidates = [&](auto f) {
        for (unsigned j = threadIdx.x; j < n_cand; j += ROW_THREADS) f(s.cand[j].y, s.cand[j].x);
    };
    // those above t1 written; those on it counted by their last 8 bits
    candidates([&](unsigned i, uint32_t k) {
        const unsigned d = (k >> 8) & (BINS - 1);
        if (d > t1.x) out[atomicAdd(&s.taken, 1u)] = table[i];
        else if (d == t1.x) atomicAdd(&s.hist[k & 0xFF], 1u);
    });
    __syncthreads();
    const uint2 t2 = hist_threshold(need, s);
    // those on t1 above t2 written; of those on t2, equal keys, any need - t2.y, after every other
    candidates([&](unsigned i, uint32_t k) {
        if (((k >> 8) & (BINS - 1)) != t1.x) return;
        if ((k & 0xFF) > t2.x) {
            out[atomicAdd(&s.taken, 1u)] = table[i];
        } else if ((k & 0xFF) == t2.x) {
            const unsigned slot = atomicAdd(&s.ties, 1u);
            if (slot < need - t2.y) out[TOPK - need + t2.y + slot] = table[i];
        }
    });
}

void run(const at::Tensor &score, const at::Tensor &lengths, const at::Tensor &page_table_size_1,
         const at::Tensor &cu_seqlens_q, at::Tensor &out_page_indices) {
    TORCH_CHECK(out_page_indices.size(1) == TOPK, "top-2048 only");
    TORCH_CHECK(score.is_contiguous() && lengths.is_contiguous() && page_table_size_1.is_contiguous() &&
                    cu_seqlens_q.is_contiguous() && out_page_indices.is_contiguous(),
                "contiguous tensors only");
    const int rows = static_cast<int>(score.size(0));
    const at::hip::OptionalHIPGuardMasqueradingAsCUDA guard(score.device());
    const hipStream_t stream = at::hip::getCurrentHIPStream();
    Params            p{};
    p.score        = score.data_ptr<float>();
    p.lengths      = lengths.data_ptr<int>();
    p.table        = page_table_size_1.data_ptr<int>();
    p.cu_seqlens   = cu_seqlens_q.data_ptr<int>();
    p.out          = out_page_indices.data_ptr<int>();
    p.n_candidates = static_cast<int>(score.size(1));
    p.n_seqs       = static_cast<int>(page_table_size_1.size(0));
    p.n_slots      = static_cast<int>(page_table_size_1.size(1));
    if (p.n_candidates <= ROW_MAX) {
        hipLaunchKernelGGL(row_kernel, dim3(rows), dim3(ROW_THREADS), 0, stream, p);
        C10_HIP_CHECK(hipGetLastError());
        return;
    }
    const int64_t state_bytes = static_cast<int64_t>(rows) * static_cast<int64_t>(sizeof(RowState));
    const int64_t cands_bytes = static_cast<int64_t>(rows) * CAP * static_cast<int64_t>(sizeof(uint2));
    at::Tensor    scratch     = at::empty({state_bytes + cands_bytes}, score.options().dtype(at::kByte));
    p.state                   = reinterpret_cast<RowState *>(scratch.data_ptr<uint8_t>());
    p.cands                   = reinterpret_cast<uint2 *>(scratch.data_ptr<uint8_t>() + state_bytes);
    // BLOCKS a pass over the rows, 21 to 85 a row, each at least TOPK positions; hist0 half as many,
    // so that fewer blocks flush their bins
    const int64_t n       = p.n_candidates;
    const int     per_row = std::clamp(BLOCKS / rows, 21, 85);
    const int     split   = static_cast<int>(std::clamp<int64_t>((n + TOPK - 1) / TOPK, 1, per_row));
    p.per_block           = static_cast<unsigned>((n + split - 1) / split);
    const int split0      = std::max(1, split / 2);
    p.per_block0          = static_cast<unsigned>((n + split0 - 1) / split0);
    C10_HIP_CHECK(hipMemsetAsync(p.state, 0, state_bytes, stream));
    const dim3 grid(rows, split);
    hipLaunchKernelGGL(hist0_kernel, dim3(rows, split0), dim3(THREADS), 0, stream, p);
    hipLaunchKernelGGL(hist1_kernel, grid, dim3(THREADS), 0, stream, p);
    hipLaunchKernelGGL(scatter_kernel, grid, dim3(THREADS), 0, stream, p);
    hipLaunchKernelGGL(refine_kernel, grid, dim3(THREADS), 0, stream, p);
    C10_HIP_CHECK(hipGetLastError());
}

} // namespace
} // namespace dsa_topk

#define TORCH_LIBRARY_EXPAND(ns, m) TORCH_LIBRARY(ns, m)
TORCH_LIBRARY_EXPAND(TORCH_EXTENSION_NAME, m) {
    m.def("run(Tensor score, Tensor lengths, Tensor page_table_size_1, Tensor cu_seqlens_q, "
          "Tensor(a!) out_page_indices) -> ()",
          &dsa_topk::run);
}
